      time: Value(time),
      state: state == null && nullToAbsent
          ? const Value.absent()
          : Value(state),
      approvalCode: approvalCode == null && nullToAbsent
          ? const Value.absent()
          : Value(approvalCode),
      cardMask: cardMask == null && nullToAbsent
          ? const Value.absent()
          : Value(cardMask),
      terminalTransactionId: terminalTransactionId == null && nullToAbsent
          ? const Value.absent()
          : Value(terminalTransactionId),
      kindId: kindId == null && nullToAbsent
          ? const Value.absent()
          : Value(kindId),
      seq: Value(seq),
      commandKey: commandKey == null && nullToAbsent
          ? const Value.absent()
          : Value(commandKey),
      reference: reference == null && nullToAbsent
          ? const Value.absent()
          : Value(reference),
      providerCode: providerCode == null && nullToAbsent
          ? const Value.absent()
          : Value(providerCode),
    );
  }

  factory Payment.fromJson(
