class CashOperation extends DataClass implements Insertable<CashOperation> {
  final int id;
  final int? storeId;
  final Decimal amount;
  final int? accountId;
  final int type;
  final int? userId;
  final String? note;
  final int? docTime;
  final int? state;

  /// Вид оплаты, **которым приняты деньги** (v47): наличные, карта, QR.
  ///
  /// До v47 не хранился, и аванс, принятый картой, уезжал оператору
  /// наличными. `null` у строк старше v47 — «не записано», а не «наличные».
  final int? kindId;
  const CashOperation({
    required this.id,
    this.storeId,
    required this.amount,
    this.accountId,
    required this.type,
    this.userId,
    this.note,
    this.docTime,
    this.state,
    this.kindId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    if (!nullToAbsent || storeId != null) {
      map['store_id'] = Variable<int>(storeId);
