    return SaleDiscountsCompanion(
      id: Value(id),
      receiptNo: Value(receiptNo),
      posId: Value(posId),
      saleProductId: Value(saleProductId),
      origin: Value(origin),
      sourceId: sourceId == null && nullToAbsent
          ? const Value.absent()
          : Value(sourceId),
      amount: Value(amount),
      time: Value(time),
    );
